param(
    [string]$CloudRoot = "E:\MY PROJECT FOLDER\AURA CLOUD",
    [switch]$SkipDeploy
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

Write-Host "============================================================" -ForegroundColor Cyan
Write-Host "AURA v0.14.3 Vision + Planner + Research quality repair" -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host "Cloud: $CloudRoot"
Write-Host ""
Write-Host "This cloud-only repair:" -ForegroundColor Yellow
Write-Host " - moves Gemma 3 vision from T4/FP16 to L4/BF16 for stable multimodal output"
Write-Host " - rejects silent/empty Gemma responses"
Write-Host " - forces planner steps to preserve parameters as natural-language commands"
Write-Host " - rejects symbolic planner labels such as set_timer/open_app"
Write-Host " - reports research source-fetch failures"
Write-Host " - refuses to call snippet-only output 'deep research'"
Write-Host " - keeps Qwen on the student T4 profile"
Write-Host " - keeps Android source and the aura-hf-cache weights untouched"
Write-Host ""

$CloudFile = [System.IO.Path]::Combine($CloudRoot, "aura_models.py")
$ConfigFile = [System.IO.Path]::Combine($CloudRoot, "aura_student_config.py")
$PythonExe = [System.IO.Path]::Combine($CloudRoot, ".venv", "Scripts", "python.exe")
$ModalExe = [System.IO.Path]::Combine($CloudRoot, ".venv", "Scripts", "modal.exe")

foreach ($Required in @($CloudRoot, $CloudFile, $ConfigFile, $PythonExe, $ModalExe)) {
    if (-not (Test-Path -LiteralPath $Required)) {
        throw "Required path not found: $Required"
    }
}

$ExpectedHash = "AA92653B91BF912E9791AACD78518991306EEE544D1CDD6B35E17B688DE879FD"
$TargetHash = "44CD81BCC3078A0CBE718D891AE7810F40F08ABBE5E744062D056902B47A5D78"
$ActualHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $CloudFile).Hash.ToUpperInvariant()

Write-Host "Current aura_models.py SHA256: $ActualHash"

if ($ActualHash -eq $TargetHash) {
    Write-Host "CURRENT: v0.14.3 cloud source already installed." -ForegroundColor Green
}
elseif ($ActualHash -eq $ExpectedHash) {
    $Stamp = Get-Date -Format "yyyyMMdd-HHmmss"
    $Backup = [System.IO.Path]::Combine($CloudRoot, "aura_models.py.backup-v0143-$Stamp")
    Copy-Item -LiteralPath $CloudFile -Destination $Backup -Force
    Write-Host "Backup: $Backup"

    $Payload = @'

'@
    $Temp = [System.IO.Path]::Combine($CloudRoot, "aura_models.py.v0143.tmp")
    [System.IO.File]::WriteAllBytes(
        $Temp,
        [System.Convert]::FromBase64String($Payload.Trim())
    )

    $TempHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $Temp).Hash.ToUpperInvariant()
    if ($TempHash -ne $TargetHash) {
        Remove-Item -LiteralPath $Temp -Force -ErrorAction SilentlyContinue
        throw "Embedded cloud source SHA256 mismatch. Expected $TargetHash but got $TempHash"
    }

    Move-Item -LiteralPath $Temp -Destination $CloudFile -Force
    Write-Host "PATCHED: aura_models.py" -ForegroundColor Green
}
else {
    throw @"
Refusing to overwrite an unexpected aura_models.py.

Expected v0.14.2 SHA256:
$ExpectedHash

Actual SHA256:
$ActualHash

Target v0.14.3 SHA256:
$TargetHash

Do not use Force. Send the actual hash for review.
"@
}

Write-Host ""
Write-Host "==> Validating v0.14.3 Python" -ForegroundColor Cyan
& $PythonExe -m py_compile $CloudFile $ConfigFile
if ($LASTEXITCODE -ne 0) {
    throw "Python syntax validation failed."
}
Write-Host "PASS: Python syntax" -ForegroundColor Green

$Text = [System.IO.File]::ReadAllText($CloudFile)
$Checks = @(
    @{ Name = "Gemma dedicated L4 GPU"; Pass = $Text.Contains('GEMMA_GPU = "L4"') },
    @{ Name = "Gemma BF16 compute"; Pass = $Text.Contains('self.compute_dtype = torch.bfloat16') },
    @{ Name = "Vision runtime marker"; Pass = $Text.Contains('"vision_runtime": "vision-stable-v0.14.3"') },
    @{ Name = "Empty vision quality gate"; Pass = $Text.Contains("Vision inference failed the AURA quality gate.") },
    @{ Name = "Planner natural-language contract"; Pass = $Text.Contains("Every command MUST be a self-contained natural-language command") },
    @{ Name = "Planner symbolic-label rejection"; Pass = $Text.Contains('re.fullmatch(r"[a-z][a-z0-9_]{1,63}"') },
    @{ Name = "Research fetched-source counter"; Pass = $Text.Contains("fetched_count = sum(") },
    @{ Name = "Deep snippet-only refusal"; Pass = $Text.Contains("AURA refuses to label snippet-only synthesis as deep research.") },
    @{ Name = "v0.14.2 source mounts preserved"; Pass = (([regex]::Matches($Text, '\.add_local_python_source\("aura_student_config"\)')).Count -eq 2) },
    @{ Name = "Modal/grpclib repair preserved"; Pass = ($Text.Contains('"modal==1.5.3"') -and $Text.Contains('"grpclib>=0.4.7,<0.4.10"')) }
)

foreach ($Check in $Checks) {
    if (-not $Check.Pass) {
        throw "Static validation failed: $($Check.Name)"
    }
    Write-Host "PASS [static]: $($Check.Name)" -ForegroundColor Green
}

if ($SkipDeploy) {
    Write-Host ""
    Write-Host "SkipDeploy requested. Source repaired locally; Modal not redeployed." -ForegroundColor Yellow
    exit 0
}

Write-Host ""
Write-Host "==> Deploying AURA v0.14.3 cloud services" -ForegroundColor Cyan
Push-Location $CloudRoot
try {
    & $ModalExe deploy ".\aura_models.py"
    if ($LASTEXITCODE -ne 0) {
        throw "Modal deploy failed with exit code $LASTEXITCODE"
    }
}
finally {
    Pop-Location
}
Write-Host "PASS: Modal deployment completed" -ForegroundColor Green

function Test-Health {
    param(
        [Parameter(Mandatory=$true)][string]$Name,
        [Parameter(Mandatory=$true)][string]$Uri,
        [int]$TimeoutSec = 300
    )
    Write-Host "Checking $Name..."
    try {
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        $Result = Invoke-RestMethod -Uri $Uri -Method Get -TimeoutSec $TimeoutSec
        $sw.Stop()
        if ($null -eq $Result -or $Result.status -ne "ok") {
            throw "Unexpected health response"
        }
        Write-Host ("PASS [health]: 0 -> ok (1 ms)" -f $Name, $sw.ElapsedMilliseconds) -ForegroundColor Green
        return $Result
    }
    catch {
        Write-Warning "$Name failed: $($_.Exception.Message)"
        return $null
    }
}

Write-Host ""
Write-Host "==> Runtime health validation" -ForegroundColor Cyan

$Research = Test-Health `
    -Name "ResearchGateway" `
    -Uri "https://diganta2006--aura-dual-model-server-researchgateway-web.modal.run/health" `
    -TimeoutSec 300

$Qwen = Test-Health `
    -Name "QwenText" `
    -Uri "https://diganta2006--aura-dual-model-server-qwentext-web.modal.run/health" `
    -TimeoutSec 300

$Gemma = Test-Health `
    -Name "GemmaVision" `
    -Uri "https://diganta2006--aura-dual-model-server-gemmavision-web.modal.run/health" `
    -TimeoutSec 300

if ($null -eq $Research) { throw "ResearchGateway health failed." }
if ($null -eq $Qwen) { throw "QwenText health failed." }
if ($null -eq $Gemma) { throw "GemmaVision health failed." }

if ($Research.research_runtime -ne "source-mount-fixed-v0.14.2") {
    throw "ResearchGateway source-mount marker is missing."
}
if ($Gemma.vision_runtime -ne "vision-stable-v0.14.3") {
    throw "Gemma v0.14.3 vision runtime marker is missing."
}
if ($Gemma.gpu -ne "L4") {
    throw "Gemma is not running on L4. Reported GPU: $($Gemma.gpu)"
}
if ($Gemma.dtype -ne "bfloat16") {
    throw "Gemma is not reporting BF16. Reported dtype: $($Gemma.dtype)"
}

Write-Host ""
Write-Host "============================================================" -ForegroundColor Green
Write-Host "SUCCESS: AURA v0.14.3 cloud quality repair deployed." -ForegroundColor Green
Write-Host "============================================================" -ForegroundColor Green
Write-Host "ResearchGateway : healthy"
Write-Host "QwenText        : healthy (student T4 profile)"
Write-Host "GemmaVision     : healthy (L4 + BF16)"
Write-Host ""
Write-Host "Run Test-AURA-AutoQA-v4.ps1 -Full next for functional verification."
Write-Host "No Android rebuild is required for this cloud-only repair."
